svg.script:
var r = { origin: String(window.origin) };
try { r.localStorage = String(window.localStorage.getItem('x')); } catch (e) { r.localStorage = e && e.name; }
try { r.cookie = String(document.cookie); } catch (e) { r.cookie = e && e.name; }
document.getElementById('s').setAttribute('data-result', JSON.stringify(r));
window.__vectorResults = [{ name: 'result', data: r }];
